// The fixed Python script that runs inside the Daytona sandbox (see sandbox.ts).
// It is a constant in code, never generated by a model. It reads one statement file
// (PDF via pdfplumber, XLSX via openpyxl, XLS via xlrd) and prints a single line:
//   EW_ROWS_JSON:{"rows":[{date, description, amount, direction, running_balance?}], ...}
// Every row is copied from a table cell or text line of the statement; the TypeScript
// side validates the rows again (parse.ts normaliseRows) before anything uses them.
// Usage: python3 parse_statement.py <pdf|xlsx|xls> <path>

export const SANDBOX_PARSER_PY = String.raw`
import json
import re
import sys
from datetime import date, datetime

MARKER = 'EW_ROWS_JSON:'
MAX_ROWS = 5000

DATE_FORMATS = (
    '%Y-%m-%d', '%m/%d/%Y', '%m/%d/%y', '%m-%d-%Y', '%Y/%m/%d',
    '%b %d, %Y', '%b %d %Y', '%B %d, %Y', '%d %b %Y', '%d-%b-%Y',
)
DATE_TOKEN = r'(\d{4}-\d{2}-\d{2}|\d{1,2}/\d{1,2}/\d{2,4})'
AMOUNT_TOKEN = r'(\(?[-−]?\$?\s?\d[\d,]*\.\d{2}\)?-?)'
TEXT_LINE = re.compile(
    r'^\s*' + DATE_TOKEN + r'\s+(.+?)\s+' + AMOUNT_TOKEN + r'(?:\s+' + AMOUNT_TOKEN + r')?\s*$'
)
OPENING_BALANCE = re.compile(
    r'(?:beginning|opening|starting|previous)\s+balance[^\d(\-$]*' + AMOUNT_TOKEN, re.IGNORECASE
)

HEADERS = {
    'date': re.compile(r'^(date|posted|posting date|post date|transaction date|trans date|value date)$'),
    'description': re.compile(r'^(description|memo|details|narrative|payee|transaction|transaction description|particulars)$'),
    'amount': re.compile(r'^(amount|amt|transaction amount)$'),
    'debit': re.compile(r'^(debit|debits|withdrawal|withdrawals|money out|paid out)$'),
    'credit': re.compile(r'^(credit|credits|deposit|deposits|money in|paid in)$'),
    'balance': re.compile(r'^(balance|running balance|running_balance|ending balance)$'),
}


def clean_header(value):
    text = re.sub(r'[^a-z_ ]', ' ', str(value if value is not None else '').lower())
    return ' '.join(text.split())


def norm_date(value):
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    text = str(value if value is not None else '').strip()
    if not text:
        return None
    text = text.split('T')[0]
    if text.endswith(' 00:00:00'):
        text = text[:-9]
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(text, fmt).date().isoformat()
        except ValueError:
            pass
    return None


def to_amount(value):
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().replace('−', '-')
    if not text:
        return None
    negative = False
    if text.startswith('(') and text.endswith(')'):
        negative = True
        text = text[1:-1]
    text = text.replace('$', '').replace(',', '').replace(' ', '')
    if text.endswith('-'):
        negative = not negative
        text = text[:-1]
    if text.startswith('-'):
        negative = not negative
        text = text[1:]
    if not re.fullmatch(r'\d+(\.\d+)?', text):
        return None
    number = float(text)
    return -number if negative else number


def find_columns(cells):
    labels = [clean_header(c) for c in cells]
    cols = {}
    for key, pattern in HEADERS.items():
        for index, label in enumerate(labels):
            if pattern.match(label):
                cols[key] = index
                break
    has_amount = 'amount' in cols or ('debit' in cols and 'credit' in cols)
    if 'date' in cols and 'description' in cols and has_amount:
        return cols
    return None


def cell(cells, cols, key):
    index = cols.get(key)
    if index is None or index >= len(cells):
        return None
    return cells[index]


def record(cells, cols):
    when = norm_date(cell(cells, cols, 'date'))
    description = ' '.join(str(cell(cells, cols, 'description') or '').split())
    if not when or not description:
        return None
    amount = None
    direction = None
    if 'amount' in cols:
        signed = to_amount(cell(cells, cols, 'amount'))
        if signed:
            amount = abs(signed)
            direction = 'out' if signed < 0 else 'in'
    else:
        debit = to_amount(cell(cells, cols, 'debit'))
        credit = to_amount(cell(cells, cols, 'credit'))
        if debit:
            amount, direction = abs(debit), 'out'
        elif credit:
            amount, direction = abs(credit), 'in'
    if not amount:
        return None
    row = {'date': when, 'description': description, 'amount': round(amount, 2), 'direction': direction}
    balance = to_amount(cell(cells, cols, 'balance')) if 'balance' in cols else None
    if balance is not None:
        row['running_balance'] = round(balance, 2)
    return row


def rows_from_table(table, cols):
    rows = []
    for raw in table:
        cells = list(raw or [])
        header = find_columns(cells)
        if header:
            cols = header
            continue
        if not cols:
            continue
        row = record(cells, cols)
        if row:
            rows.append(row)
    return rows, cols


def rows_from_text(text, prev_balance):
    # Unsigned amounts take their direction from the running balance, starting from a
    # printed opening balance when there is one.
    rows = []
    for line in (text or '').splitlines():
        opening = OPENING_BALANCE.search(line) if prev_balance is None and not rows else None
        if opening:
            prev_balance = to_amount(opening.group(1))
            continue
        match = TEXT_LINE.match(line)
        if not match:
            continue
        when = norm_date(match.group(1))
        description = ' '.join(match.group(2).split())
        signed = to_amount(match.group(3))
        balance = to_amount(match.group(4)) if match.group(4) else None
        if not when or not description or not signed:
            continue
        if signed < 0:
            direction = 'out'
        elif balance is not None and prev_balance is not None:
            direction = 'in' if balance >= prev_balance else 'out'
        else:
            direction = 'in'
        row = {'date': when, 'description': description, 'amount': round(abs(signed), 2), 'direction': direction}
        if balance is not None:
            row['running_balance'] = round(balance, 2)
            prev_balance = balance
        rows.append(row)
    return rows, prev_balance


def parse_pdf(path):
    import pdfplumber
    rows = []
    cols = None
    prev_balance = None
    method = 'table'
    with pdfplumber.open(path) as pdf:
        for page in pdf.pages:
            page_rows = []
            for table in page.extract_tables() or []:
                found, cols = rows_from_table(table, cols)
                page_rows.extend(found)
            if not page_rows:
                page_rows, prev_balance = rows_from_text(page.extract_text() or '', prev_balance)
                if page_rows:
                    method = 'text'
            elif 'running_balance' in page_rows[-1]:
                prev_balance = page_rows[-1]['running_balance']
            rows.extend(page_rows)
            if len(rows) >= MAX_ROWS:
                break
    return rows, method


def parse_xlsx(path):
    import openpyxl
    book = openpyxl.load_workbook(path, read_only=True, data_only=True)
    rows = []
    for sheet in book.worksheets:
        found, _ = rows_from_table([list(r) for r in sheet.iter_rows(values_only=True)], None)
        rows.extend(found)
    return rows, 'sheet'


def parse_xls(path):
    import xlrd
    book = xlrd.open_workbook(path)
    rows = []
    for sheet in book.sheets():
        table = []
        for r in range(sheet.nrows):
            cells = []
            for c in range(sheet.ncols):
                item = sheet.cell(r, c)
                if item.ctype == xlrd.XL_CELL_DATE:
                    cells.append(xlrd.xldate_as_datetime(item.value, book.datemode))
                else:
                    cells.append(item.value)
            table.append(cells)
        found, _ = rows_from_table(table, None)
        rows.extend(found)
    return rows, 'sheet'


def main():
    kind, path = sys.argv[1], sys.argv[2]
    parsers = {'pdf': parse_pdf, 'xlsx': parse_xlsx, 'xls': parse_xls}
    if kind not in parsers:
        raise ValueError('unsupported file kind ' + kind)
    rows, method = parsers[kind](path)
    print(MARKER + json.dumps({'rows': rows[:MAX_ROWS], 'method': method}))


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        print(MARKER + json.dumps({'rows': [], 'error': (type(error).__name__ + ': ' + str(error))[:300]}))
`;
